export const DATA_25: ReadingTest[] = [
  { id: "rd-031", num: 31, title: "Đề 031", timeMin: 60, parts: [
    { title: "Ana's New Laptop", paragraphs: ["Ana's old laptop had served her well through college, but by her final semester, the screen flickered constantly and the battery rarely lasted more than twenty minutes without being plugged into an outlet. After watching it freeze in the middle of an important assignment for the third time that week, she finally admitted the machine had reached the end of its useful life. Rather than buying the first affordable model she saw, however, Ana decided to spend a few days comparing options before committing any of her carefully saved money.", "She began by listing exactly what she needed the laptop to do, since a machine built for gaming would cost far more than one suited to writing papers and browsing the internet. Visiting three different electronics stores in person let her physically test keyboards and screen brightness in ways that online photos never could. At the same time, she kept a spreadsheet comparing prices, storage capacity, and battery life across every model she considered, since a salesperson's recommendation, however friendly, was not always the option that best matched her actual budget and needs. She updated it every evening after visiting a new store, since even minor details could change her final decision considerably.", "After nearly a week of comparing, Ana settled on a mid-range model with enough storage for her design software and a battery advertised to last most of a school day. Setting it up at home, however, proved less straightforward than she expected. A software update that seemed to freeze halfway through left her staring at a blank screen for almost twenty minutes, convinced she had somehow damaged a brand-new machine on its very first day. A call to customer support eventually revealed that the update was simply taking longer than usual and that interrupting it would have caused far more serious problems. The whole ordeal, though stressful in the moment, taught her that even simple software updates deserve patience rather than panic.", "The experience left Ana more cautious about how she treated her new laptop going forward. She began saving important files to an external drive every weekend, a habit her old machine's sudden failure had never taught her to adopt. She also read through the laptop's manual, something she admitted she had never once done with any previous device, and discovered several battery-saving settings that noticeably extended how long she could work before needing to find an outlet.", "Months later, Ana still considers the laptop one of the better purchases she has made, not simply because of its performance but because of what the whole process taught her about researching a decision rather than rushing into it. When friends ask for advice before buying their own laptops, she now walks them through the same comparison spreadsheet she built for herself, insisting that a few extra days of careful research are almost always worth the wait."], questions: [{ q: "According to the passage, what actually caused the blank screen after Ana's laptop update?", options: ["The laptop's battery had failed completely during the update.", "Ana had accidentally damaged the machine on its first day.", "Customer support said the laptop needed to be returned immediately.", "The update was taking longer than expected, not damaging the machine."], answer: 3 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Careful research helped Ana choose and use her laptop wisely.", "Ana regretted not buying the very first laptop she saw.", "Ana successfully fixed a frozen software update by calling support.", "Everyone who buys a laptop should always call customer support first."], answer: 0 }, { q: "The word \"committing\" in paragraph 1 is closest in meaning to _______.", options: ["saving", "spending", "investing", "commuting"], answer: 1 }, { q: "According to the passage, what new habit did Ana adopt after the incident?", options: ["She stopped using her laptop for schoolwork entirely.", "She read through the laptop's manual for the first time.", "Saving important files to an external drive every weekend.", "She returned the laptop to the store for a refund."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as something Ana did while comparing laptops?", options: ["Listing exactly what she needed the laptop to do.", "Reading professional laptop reviews published in a technology magazine.", "Visiting three different electronics stores to test keyboards.", "Keeping a spreadsheet comparing prices and battery life."], answer: 1 }, { q: "The word \"it\" in paragraph 2 refers to _______.", options: ["a new store", "her final decision", "her comparison spreadsheet", "battery life details"], answer: 2 }, { q: "According to the passage, what does Ana now do when friends ask for laptop advice?", options: ["She shows them the same comparison spreadsheet she built.", "She insists friends should never spend money on laptops.", "She tells them to buy the exact same laptop model.", "She refuses to give any laptop advice to friends now."], answer: 0 }, { q: "The word \"extended\" in paragraph 4 is closest in meaning to _______.", options: ["shortened", "protected", "extorted", "lengthened"], answer: 3 }, { q: "What can be inferred about Ana's future purchasing habits, based on the passage?", options: ["Software updates always cause permanent damage to new laptops.", "Ana will likely research carefully before major purchases in the future.", "Ana's friends will stop asking her for any advice at all.", "Ana will never buy another laptop for the rest of her life."], answer: 1 }, { q: "What is the author's overall purpose in telling Ana's story?", options: ["To promote a specific laptop brand or particular store.", "To warn readers never to trust customer support services.", "To share a relatable lesson about careful, patient decision-making.", "To criticize Ana for waiting too long to buy a laptop."], answer: 2 }] },
    { title: "The Evolution of ASEAN Cooperation", paragraphs: ["Founded in 1967 amid Cold War anxieties about regional instability, the Association of Southeast Asian Nations began as a modest diplomatic mechanism intended primarily to reduce the risk of open conflict among neighboring states with sharply different political systems and historical grievances. What started as a forum for managing distrust gradually accumulated a far broader mandate, expanding over subsequent decades into economic coordination, environmental cooperation, and a collective diplomatic voice that individual member states, acting alone, would have struggled to project on the international stage.", "It is the deliberate pursuit of economic interdependence, more than shared political ideology, that has arguably done the most to keep ASEAN's member states cooperating through periods of significant political disagreement. The ASEAN Free Trade Area, launched in the early 1990s, progressively reduced tariffs among member economies whose development levels ranged from among the wealthiest in Asia to some of the least industrialized, an asymmetry that complicated implementation considerably. Subsequent agreements extended this integration into services, investment, and eventually a broader ambition toward a single production base intended to rival other regional trading blocs.", "Central to how ASEAN operates is a decision-making norm often called the \"ASEAN Way,\" which prioritizes consensus and non-interference in members' internal affairs over binding majority votes or centralized enforcement mechanisms. Proponents argue this approach has allowed the organization to include politically diverse members who might otherwise refuse to participate at all, preserving unity that a more confrontational model may have fractured. Critics counter that consensus-based decision-making tends to produce agreements calibrated to the least willing member, meaning ambitious proposals are frequently diluted into commitments too modest to meaningfully change behavior on contentious issues.", "This consensus requirement interacts uncomfortably with the significant development gaps separating ASEAN's founding members from those that joined later, particularly in mainland Southeast Asia. A trade or labor-mobility agreement that a wealthier member can implement with minimal disruption may impose genuinely difficult adjustment costs on a less industrialized economy still building basic regulatory capacity, meaning uniform commitments negotiated at the regional level do not translate into uniform readiness on the ground. Some economists argue that this asymmetry has quietly slowed the pace of deeper integration more than any single political disagreement has.", "External pressures further complicate ASEAN's internal cohesion, particularly competition between larger external powers seeking influence within the region and unresolved territorial disputes in the South China Sea that directly involve several member states. Because ASEAN's consensus norm requires broad agreement before the organization can issue a unified position, disputes affecting only some members can leave the bloc unable to articulate a collective response, a limitation that critics argue undermines ASEAN's credibility as a unified diplomatic actor precisely on the issues where unified action might matter most.", "Beyond economics and security, ASEAN has expanded cooperation into education exchanges, cross-border labor mobility frameworks, and cultural programs intended to build a shared regional identity among younger citizens. Some officials describe this social dimension as increasingly central to ASEAN's long-term cohesion, though it would be an overstatement to suggest a genuinely unified regional identity has emerged; surveys suggest most citizens across member states continue to identify considerably more strongly with their national identity than with any broader ASEAN affiliation, even among those who have participated directly in regional exchange programs.", "Taken as a whole, ASEAN's trajectory reflects real, cumulative achievement without approaching anything resembling the deeper political and economic union some early proponents once envisioned. Whether the organization's consensus-based model will prove resilient enough to manage intensifying external pressures and internal development gaps over the coming decades, or will instead require a more binding institutional structure it has so far resisted adopting, remains a question current trends do not yet allow anyone to answer with confidence."], questions: [{ q: "According to the passage, what complicated the implementation of the ASEAN Free Trade Area?", options: ["The agreement extended integration into services and investment areas.", "All ASEAN member economies were equally wealthy and industrialized.", "Member economies had very different levels of industrial development.", "Tariffs among member economies increased sharply after the agreement."], answer: 2 }, { q: "The word \"asymmetry\" in paragraph 2 is closest in meaning to _______.", options: ["imbalance", "symmetry", "agreement", "asymmetric"], answer: 0 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["The ASEAN Free Trade Area is ASEAN's most important achievement.", "ASEAN has achieved real cooperation without becoming a full political union.", "ASEAN has already become a fully unified political and economic union.", "Every ASEAN member now shares an identical national identity and outlook."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a challenge facing ASEAN?", options: ["Significant development gaps among founding and later-joining members.", "Unresolved territorial disputes in the South China Sea.", "A consensus norm that can dilute ambitious regional proposals.", "A formal military alliance requiring joint defense commitments."], answer: 3 }, { q: "According to the passage, what do critics say happens to ambitious proposals under the \"ASEAN Way\"?", options: ["Agreements often get diluted to match the least willing member.", "The approach lets politically diverse members participate at all.", "Consensus decision-making has been formally replaced by majority voting.", "All ASEAN members always agree quickly on every major proposal."], answer: 0 }, { q: "The phrase \"This consensus requirement\" in paragraph 4 refers to _______.", options: ["binding majority votes", "the ASEAN Way norm", "internal affairs itself", "centralized enforcement power"], answer: 1 }, { q: "The word \"diluted\" in paragraph 3 is closest in meaning to _______.", options: ["strengthened", "clarified", "diluvial", "weakened"], answer: 3 }, { q: "According to the passage, what limitation does ASEAN's consensus norm create regarding the South China Sea disputes?", options: ["External powers have no real interest in Southeast Asian influence.", "ASEAN always issues a swift, unified response to every regional dispute.", "Disputes affecting only some members can leave ASEAN without a unified response.", "Territorial disputes in the South China Sea involve several member states."], answer: 2 }, { q: "What can be inferred about ASEAN's future, based on the passage as a whole?", options: ["ASEAN's future cohesion may depend on how it handles growing external pressure.", "ASEAN will definitely adopt a binding federal structure within a decade.", "Reduced external pressure will directly cause ASEAN to abandon consensus decision-making.", "The ASEAN Free Trade Area reduced tariffs among member economies."], answer: 0 }, { q: "What is the author's overall purpose in describing ASEAN's evolution?", options: ["To celebrate ASEAN as history's most successful regional organization.", "To give a balanced account of ASEAN's real progress and real limits.", "To criticize member states for refusing closer political union.", "To argue that ASEAN should be dissolved as soon as possible."], answer: 1 }] },
    { title: "The Physical and Mental Demands of Mountaineering", paragraphs: ["Mountaineering occupies an unusual position among physically demanding pursuits, since success or failure depends less on any single measurable capacity, such as cardiovascular endurance or muscular strength, than on how effectively a climber integrates physical conditioning with psychological composure under conditions that steadily erode both. Unlike many endurance sports conducted at predictable intensity, high-altitude climbing subjects the body to a deteriorating environment even as physical effort remains constant or increases, a combination that distinguishes it from activities where the environment itself does not actively work against the athlete's continued performance.", "It is the progressive scarcity of oxygen at altitude, more than cold or physical exertion in isolation, that ultimately limits how high and how quickly a climber can safely ascend. Above roughly five thousand meters, atmospheric pressure drops enough that even a well-acclimatized body struggles to deliver sufficient oxygen to working muscles and the brain, producing a physiological state that no amount of prior fitness can fully offset. Climbers ascending too quickly for their body's acclimatization pace risk altitude sickness that can, in its most severe forms, prove fatal within hours rather than days.", "Cognitive function appears to deteriorate meaningfully under sustained hypoxia, though the precise threshold and severity vary considerably between individuals for reasons researchers do not yet fully understand. Climbers at extreme altitude commonly report impaired judgment, slowed decision-making, and occasionally hallucinations severe enough to prompt otherwise experienced mountaineers toward decisions that would seem obviously dangerous at sea level. Some researchers suggest that this impairment may explain a disproportionate share of summit-day fatalities, since the very altitude that makes a summit meaningful also degrades the judgment needed to descend safely once it is reached.", "Physical conditioning alone does not reliably predict who copes well with this cognitive strain, a finding that has reshaped how serious expeditions approach training. Some climbers with exceptional cardiovascular fitness perform poorly under the compounding stress of cold, fatigue, and diminished judgment, while others with more modest physical conditioning demonstrate a capacity to make sound decisions precisely when altitude-induced impairment is at its worst. This dissociation between physical preparation and psychological resilience under hypoxic stress has led several expedition leaders to prioritize candidates with demonstrated composure under pressure over those with the most impressive fitness metrics alone.", "Group dynamics introduce a further layer of risk that individual physiological data cannot capture. So-called summit fever, a documented tendency to continue climbing past a predetermined turnaround time despite mounting evidence that conditions have deteriorated, appears to intensify when a climber has invested substantial money, time, and public expectation into reaching a particular peak. Experienced guides describe turnaround discipline, the willingness to abandon a summit attempt regardless of proximity, as a skill distinct from and occasionally in tension with the physical capacity that got a climber close enough to be tempted in the first place.", "Improvements in weather forecasting, satellite communication, and rescue technology have measurably reduced certain categories of mountaineering fatality, particularly deaths from being caught unprepared by sudden weather changes. These same improvements, some researchers caution, may have inadvertently encouraged less experienced climbers to attempt routes that would previously have been considered beyond their skill level, on the assumption that technology would compensate for inexperience if conditions worsened unexpectedly. Whether improved safety technology has produced a net reduction in mountaineering fatalities, once this behavioral adjustment is accounted for, remains genuinely disputed among researchers studying accident statistics.", "Taken together, mountaineering's demands resist reduction to physical training alone, since the sport's most consequential decisions are frequently made by minds already compromised by the very environment those decisions are meant to navigate. Whether future training programs will more deliberately cultivate the psychological resilience the evidence increasingly suggests matters as much as physical conditioning, or will continue treating fitness as the primary measure of readiness, remains an open question within the climbing community."], questions: [{ q: "According to the passage, what primarily limits how high and quickly a climber can safely ascend?", options: ["Cold temperatures alone primarily determine safe ascent speed.", "Physical fitness alone can fully offset high-altitude oxygen scarcity.", "The progressively decreasing availability of oxygen at high altitude.", "Altitude sickness can prove fatal within hours in severe cases."], answer: 2 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Success in mountaineering depends on both physical and psychological readiness.", "Cognitive impairment at altitude explains most summit-day fatalities.", "Physical fitness alone reliably determines mountaineering success or failure.", "Every experienced climber avoids all judgment errors at extreme altitude."], answer: 0 }, { q: "The word \"dissociation\" in paragraph 4 is closest in meaning to _______.", options: ["a connection", "a disconnect", "a diagnosis", "a discussion"], answer: 1 }, { q: "According to the passage, what does the passage say intensifies summit fever?", options: ["Turnaround discipline is a skill distinct from physical capacity.", "Summit fever mainly affects climbers with the least experience.", "Guides say turnaround discipline always increases as altitude rises.", "It intensifies with heavy prior investment in reaching a peak."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a documented mountaineering risk factor?", options: ["Impaired judgment and slowed decision-making at extreme altitude.", "A documented rise in the total number of trained mountain guides.", "Summit fever driving climbers past a planned turnaround time.", "Technology encouraging less experienced climbers toward risky routes."], answer: 1 }, { q: "The phrase \"this impairment\" in paragraph 3 refers to _______.", options: ["judgment and decision impairment", "severe hallucinations", "experienced mountaineers themselves", "obviously dangerous decisions"], answer: 0 }, { q: "The word \"inadvertently\" in paragraph 6 is closest in meaning to _______.", options: ["deliberately", "inaudibly", "unintentionally", "invariably"], answer: 2 }, { q: "According to the passage, what concern do some researchers raise about improved safety technology?", options: ["Rescue technology has completely eliminated all mountaineering fatalities.", "Experienced climbers alone benefit from improved weather forecasting.", "Improved forecasting and satellite communication have reduced several specific fatality categories recently.", "Some climbers may attempt harder routes assuming technology will compensate."], answer: 3 }, { q: "What can be inferred about the future of mountaineering training, based on the passage?", options: ["Future training may increasingly emphasize psychological resilience alongside fitness.", "Physical fitness will soon become completely irrelevant to climbing safety.", "Better psychological resilience will directly cause easier oxygen acclimatization.", "Cognitive function appears to deteriorate meaningfully under sustained hypoxia."], answer: 0 }, { q: "What is the author's overall attitude toward the demands of mountaineering, as conveyed in the passage?", options: ["Strongly critical of climbers who ignore turnaround time discipline.", "Fully confident that technology has solved every major climbing risk.", "Measured and analytical, emphasizing complexity over simple heroics.", "Mildly dismissive of the psychological challenges climbers actually face."], answer: 2 }] },
    { title: "Circular Economy: A Paradigm Shift in Modern Production", paragraphs: ["For most of the industrial era, manufacturing has operated according to a linear logic that extracts raw materials, transforms them into products, and eventually discards those products as waste once their useful life ends, a sequence so deeply embedded in production systems that alternatives were, until recently, treated as a marginal concern for environmentalists rather than a serious business strategy. The circular economy inverts this logic, treating discarded materials not as an endpoint but as an input to be recovered, repaired, or repurposed, ideally keeping resources circulating within productive use for as long as physically possible.", "It is the prospect of reduced long-term material costs, more than environmental concern in isolation, that has persuaded a growing number of manufacturers to experiment with circular production models. Extracting and processing virgin raw materials has become measurably more expensive as easily accessible deposits deplete, while recovered materials, once properly sorted and processed, can in some cases undercut virgin material costs significantly. This economic logic, companies increasingly argue, transforms circularity from a reputational gesture into a genuine cost-management strategy, though the transition costs required to redesign existing production lines remain substantial enough to deter smaller manufacturers operating on thinner margins.", "Designing products so that components can be readily disassembled, sorted, and recovered at end of life introduces engineering tradeoffs that manufacturers do not always resolve in favor of circularity. A product engineered for easy disassembly may sacrifice some durability, water resistance, or structural integrity compared to a permanently sealed alternative, meaning designers must weigh a longer eventual recovery value against a potentially shorter or less robust primary use phase. Some engineers argue this tradeoff is narrowing as materials science advances, though others maintain that genuinely circular design still typically requires accepting some compromise in a product's primary-use performance.", "Recycling itself faces a limit that circular-economy advocates do not always acknowledge with equal clarity: most materials degrade somewhat with each processing cycle, meaning recycled material typically cannot sustain infinite reuse at consistent quality without occasional input of virgin material to offset accumulated degradation. Paper fibers shorten with repeated recycling until they become too weak for structural use; certain plastics lose polymer chain integrity in ways that limit how many times they can be reprocessed before quality drops below what most applications require. This does not undermine the case for circularity so much as clarify that it functions as a means of significantly extending, rather than eliminating, the need for virgin material extraction.", "Whether voluntary corporate adoption alone can drive circular practices at the scale required, or whether binding regulation is necessary to overcome the coordination problems inherent in redesigning entire supply chains, remains genuinely contested. Some economists argue that regulation is likely necessary because individual firms adopting circular practices unilaterally may face a competitive disadvantage against rivals that do not, absent a level playing field enforced externally. Others contend that voluntary adoption, driven by the cost incentives described earlier, may prove sufficient in sectors where recovered-material savings are large enough to offset transition costs without regulatory pressure, though this sufficiency likely varies considerably by industry rather than holding uniformly across all sectors.", "Consumer behavior introduces a further complication that supply-side redesign alone cannot resolve. Take-back and repair programs depend on consumers actually participating, returning products or choosing repair over replacement, a behavior that surveys suggest remains inconsistent even among consumers who express strong general support for circular principles in the abstract. Some researchers attribute this gap to inconvenience and cost rather than indifference, suggesting that circular consumer behavior may increase substantially if take-back logistics become as frictionless as disposal currently is, though this remains a projection rather than a demonstrated outcome.", "Taken together, the circular economy represents a genuine reorientation of industrial logic rather than a fully realized alternative to linear production, since material degradation limits, design tradeoffs, and uneven adoption incentives constrain how completely circularity can be achieved with current technology and policy. Whether these constraints will loosen substantially as technology and regulation mature, or will instead persist as structural limits on how circular modern production can ever genuinely become, remains a question current evidence does not settle with confidence."], questions: [{ q: "According to the passage, what has increasingly persuaded manufacturers to adopt circular production models?", options: ["Environmental concern alone has driven most manufacturers toward circularity.", "The prospect of lower long-term material costs, more than environmental concern alone.", "Virgin raw materials have become measurably cheaper in recent years.", "Transition costs remain substantial enough to deter smaller manufacturers."], answer: 1 }, { q: "The word \"offset\" in paragraph 4 is closest in meaning to _______.", options: ["compensate for", "increase", "outsource", "upset"], answer: 0 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Recycled materials degrade in quality with each processing cycle.", "Circular production has already fully eliminated the need for virgin materials.", "Every manufacturer worldwide has now fully adopted circular production methods.", "Circular economy meaningfully extends resource use but faces real structural limits."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a limitation facing the circular economy?", options: ["Paper fibers shortening and weakening after repeated recycling cycles.", "A global ban recently imposed on all virgin material extraction.", "Some manufacturers deterred by substantial production-line redesign costs.", "Consumer participation in take-back programs remaining notably inconsistent."], answer: 1 }, { q: "According to the passage, why do some economists argue that regulation is likely necessary for circular adoption?", options: ["Regulation may be necessary since acting alone can disadvantage individual firms competitively.", "Regulation is definitely required for any circular economy to succeed at all.", "All firms in every industry face identical competitive disadvantages without regulation.", "Competitive disadvantage among firms is what causes regulation to be introduced."], answer: 0 }, { q: "The phrase \"this gap\" in paragraph 6 refers to _______.", options: ["circular principles support", "repair versus replacement", "inconsistent participation", "take-back logistics themselves"], answer: 2 }, { q: "The word \"unilaterally\" in paragraph 5 is closest in meaning to _______.", options: ["acting alone", "acting together", "acting officially", "universally"], answer: 0 }, { q: "According to the passage, what tradeoff does designing for easy disassembly sometimes involve?", options: ["Circular design always improves a product's durability and performance.", "Permanently sealed products are always easier to disassemble and recover.", "Easier disassembly can reduce a product's durability or structural integrity.", "Some engineers argue this tradeoff is narrowing as materials science advances."], answer: 2 }, { q: "What can be inferred about the long-term trajectory of the circular economy, based on the passage?", options: ["Circularity will likely keep expanding without fully replacing resource extraction.", "Virgin material extraction will definitely end completely within a few decades.", "Reduced material degradation will directly cause more consumers to recycle.", "Consumer participation in take-back programs remains notably inconsistent currently."], answer: 0 }, { q: "What is the author's overall attitude toward the circular economy, as conveyed in the passage?", options: ["Strongly enthusiastic that circular economy will solve all environmental problems.", "Deeply skeptical that circular economy offers any meaningful environmental benefit.", "Mildly critical of manufacturers for resisting circular economy adoption fully.", "Cautiously analytical, weighing genuine promise against real constraints."], answer: 3 }] },
  ] },
  { id: "rd-176", num: 176, title: "Đề 176", timeMin: 60, parts: [
    { title: "What Will English Look Like in the Future?", paragraphs: ["English is currently used by more people around the world than any other language, whether as a first language, a second language, or a foreign language learned in school. Business meetings, scientific papers, airline announcements, and even song lyrics from many different countries are often written or spoken in English. Because so many people already depend on it for daily communication, many experts have started asking an interesting question: what will English actually look like in fifty or a hundred years from now?", "One clear trend is that non-native speakers of English already outnumber native speakers by a wide margin , and this gap is expected to grow even larger in the coming decades. As more people in Asia, Africa, and South America learn English mainly to communicate with each other, rather than with speakers from Britain or the United States, a simpler, more practical version of the language is slowly emerging. Some linguists call this version 'Global English,' a form that borrows fewer complicated idioms and instead focuses on clear, direct sentences that almost anyone can understand quickly.", "Technology is also expected to shape the future of English in ways that were hard to imagine only twenty years ago. Powerful translation tools built into phones and computers already allow people to communicate across languages almost instantly, which raises the question of whether fewer people will feel the need to study English carefully in the future. At the same time, social media platforms continue to spread new English words and expressions around the world at remarkable speed, meaning the language keeps changing and growing even as translation technology becomes more common.", "Many linguists predict that English grammar itself will likely become somewhat simpler over time, following a pattern seen in other widely used languages throughout history. Irregular verb forms, for example, are gradually being replaced by regular ones in casual speech, and complicated tenses are increasingly avoided in international business communication. New vocabulary, meanwhile, continues to enter English from many other languages, reflecting the mixed cultural backgrounds of everyone now using it. This constant borrowing and simplifying is not new, but the pace at which it is happening today appears unusually fast.", "Not everyone agrees, however, that English will keep its current position forever. A number of researchers point out that languages such as Mandarin Chinese and Spanish are also growing quickly in influence, particularly as the economic power of the countries that speak them continues to rise. Whether English remains the world's leading language, gradually shares that position with others, or eventually gives way to a different global language altogether, most experts agree on one thing: the English spoken decades from now will almost certainly sound noticeably different from the English spoken today."], questions: [{ q: "What is the main idea of the passage?", options: ["English grammar will remain exactly the same forever because most speakers refuse to accept new changes", "English will completely disappear as a global language once translation tools become fully advanced everywhere", "English is likely to keep changing and simplifying as more non-native speakers use it worldwide", "English will soon be replaced entirely by Mandarin Chinese as the single most important business language"], answer: 2 }, { q: "According to the passage, non-native English speakers currently _______.", options: ["speak English less fluently than native speakers on average", "are expected to stop using English within the next decade", "mainly learn English to communicate with British or American speakers", "already outnumber native English speakers by a wide margin"], answer: 3 }, { q: "The word \"margin\" in paragraph 2 is closest in meaning to _______.", options: ["difference", "opinion", "agreement", "mistake"], answer: 0 }, { q: "According to the passage, English is mentioned as being used in all of the following EXCEPT _______.", options: ["scientific papers", "song lyrics", "political election campaigns", "business meetings"], answer: 2 }, { q: "According to the passage, what effect might advanced translation technology have, according to some experts?", options: ["It will make English grammar permanently fixed and unchangeable forever", "It will completely stop the spread of new English words online", "It will force all countries to adopt a single shared language soon", "It raises the question of whether fewer people will study English"], answer: 3 }, { q: "The word \"it\" in paragraph 4 refers to _______.", options: ["irregular verb forms", "complicated tenses", "borrowing and simplifying", "business communication"], answer: 2 }, { q: "According to the passage, what change is happening to irregular verb forms in casual speech?", options: ["They are gradually being replaced by regular verb forms", "They are being taught more intensively in English classrooms", "They are becoming more common in formal business writing", "They have completely disappeared from spoken English already"], answer: 0 }, { q: "The word \"remarkable\" in paragraph 3 is closest in meaning to _______.", options: ["impressive", "predictable", "accidental", "confusing"], answer: 0 }, { q: "It can be inferred from the passage that the author believes _______.", options: ["Mandarin Chinese will definitely replace English as the leading global language within a decade", "technology will soon make learning any language completely unnecessary for everyone", "the exact future of English is uncertain, even though some form of change seems inevitable", "English's dominant global position is guaranteed to remain unchanged for the next century"], answer: 2 }, { q: "What is the author's primary purpose in writing this passage?", options: ["to argue strongly that English should be replaced by a simpler constructed language", "to criticize non-native speakers for changing English grammar and vocabulary too quickly", "to promote a specific translation technology product to international business readers", "to explore several possible ways English might change and remain influential in the future"], answer: 3 }] },
    { title: "The Ornamental Plant Boom of the Early 1990s", paragraphs: ["Although the cultivation of ornamental plants might, at first glance, appear to be a purely aesthetic pursuit largely disconnected from broader economic or social forces, the sudden surge of interest in this hobby during the early 1990s suggests a more complicated picture. Within a remarkably short span of years, what had previously been a relatively modest, largely rural pastime transformed into a widespread urban phenomenon, one that touched households across a broad range of income levels and, in doing so, revealed something about the period itself that garden history alone cannot fully explain.", "The timing of this shift was, in all likelihood, not coincidental. Following a period of significant economic reform, many households found themselves, often for the first time in over a decade, with a measure of discretionary income that extended beyond the strict necessities of daily life. Ornamental plants, being relatively inexpensive compared to other optional purchases yet visually striking enough to signal a certain level of comfort, occupied a peculiar middle ground: accessible enough for widespread adoption, yet distinctive enough to function as a quiet marker of newfound prosperity, particularly among households eager to display that recovery without appearing overtly extravagant.", "This dimension of quiet display should not be underestimated. Certain species, particularly slow-growing bonsai specimens shaped meticulously over several years, came to function almost as a form of social currency, their value derived not merely from rarity but from the patience and cultivation skill their appearance implied. Neighbors would frequently compare collections, and informal competitions, sometimes formalized into small local exhibitions, encouraged enthusiasts to invest considerable time refining a single specimen's shape. What began as a private hobby, in other words, gradually acquired a distinctly public, even competitive dimension that its earlier, more solitary practitioners might scarcely have recognized.", "Urban space itself was reshaped, in smaller but still meaningful ways, by this trend. Balconies, once used mainly for drying laundry or storing household items, were increasingly cleared to accommodate rows of potted plants, while courtyards in older housing developments filled with arrangements that residents tended daily, often before work. Architects and urban planners writing at the time occasionally noted, with a mixture of approval and mild concern, that this informal greening of dense residential areas had emerged almost entirely from residents' own initiative, without any coordinated municipal planning behind it.", "Institutional structures soon followed this grassroots enthusiasm rather than preceding it. Local gardening clubs, many organized informally at first around a handful of enthusiastic neighbors, gradually formalized into associations with regular meetings, shared resources, and occasional competitions judged by more experienced members. Specialized magazines and pamphlets, offering guidance on pruning techniques, soil composition, and seasonal care, began appearing with increasing frequency, feeding a demand for expertise that had, until then, been passed along mostly through informal conversation between neighbors rather than through any published source.", "Not every observer viewed the trend favorably, however. Some critics, writing somewhat later in the decade, argued that the rapid rise in demand for particular rare or slow-growing species had encouraged unsustainable collection practices, with certain wild specimens removed from their natural habitats to satisfy collectors willing to pay a premium for authenticity over commercially propagated alternatives. Whether this criticism reflected a genuine ecological concern or simply a broader unease about consumerism dressed in a more traditional, seemingly wholesome form remains, even now, a matter of some historical debate.", "Regardless of how one evaluates it in retrospect, the ornamental plant boom of the early 1990s left a lasting imprint on urban domestic space that persists, in altered form, today. Many of the gardening associations founded during that decade continue to operate, and the balconies transformed then remain, for many households, spaces defined as much by cultivation as by any of their original practical functions."], questions: [{ q: "According to the passage, what economic development is most closely linked to the early-1990s rise in ornamental plant cultivation?", options: ["a sharp increase in wages paid specifically to agricultural workers", "many households gaining disposable income following economic reform", "a nationwide decrease in the price of imported luxury goods", "the introduction of new government subsidies for gardening equipment"], answer: 1 }, { q: "The word \"discretionary\" in paragraph 2 is closest in meaning to _______.", options: ["essential", "borrowed", "non-essential", "taxed"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["The plant trend focused primarily on protecting rare environmental species.", "The plant trend reflected economic prosperity, social status, and urbanization.", "The plant trend was caused entirely by nationwide government gardening campaigns.", "The plant trend declined rapidly without leaving any lasting urban impact."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as part of the ornamental plant trend's development?", options: ["local gardening clubs formalizing into associations", "magazines offering guidance on pruning and soil care", "government-funded municipal parks built for public gardening", "balconies being cleared of laundry and storage items"], answer: 2 }, { q: "According to the passage, why did certain bonsai specimens function as a form of social currency?", options: ["because government officials personally awarded prizes for the best specimens", "because their value reflected the patience and skill their appearance implied", "because they could easily be exchanged for other household goods", "because they were the least expensive plants available at local markets"], answer: 1 }, { q: "The word \"their\" in paragraph 3 (in the phrase \"their value derived\") refers to _______.", options: ["local exhibitions", "informal competitions", "bonsai specimens", "neighboring households"], answer: 2 }, { q: "According to the passage, what did architects and urban planners note about the greening of residential balconies and courtyards?", options: ["that it required government approval before residents could participate", "that it emerged largely from residents' own initiative without coordination", "that it decreased significantly the overall value of urban housing", "that it was organized entirely through official municipal planning programs"], answer: 1 }, { q: "The word \"meticulously\" in paragraph 3 is closest in meaning to _______.", options: ["accidentally", "cheaply", "quickly", "carefully"], answer: 3 }, { q: "Based on the passage, it can be inferred that critics who linked the plant trend to consumerism were most likely responding to _______.", options: ["evidence that municipal governments had funded excessive advertising campaigns for gardening products", "the fact that ornamental plants had become entirely too expensive for most households to afford", "research proving definitively that all rare plant species had been permanently destroyed", "a tension between the trend's modest origins and its later resemblance to status-driven spending"], answer: 3 }, { q: "What is the author's primary purpose in writing this passage?", options: ["To examine the social and economic impact of the trend.", "To argue that plant collecting caused severe ecological damage.", "To provide a practical guide for growing bonsai plants.", "To celebrate the trend uncritically as a positive development."], answer: 0 }] },
    { title: "Earth Hour and Its Unintended Consequences", paragraphs: ["Each year in late March, hundreds of millions of people in more than a hundred countries switch off their lights for a single hour, an act that has, over the better part of two decades, become one of the most recognizable public gestures in the environmental calendar. Yet for all the goodwill it generates, mounting evidence suggests that Earth Hour's actual contribution to reducing global carbon emissions is, at best, negligible — a conclusion that sits uneasily alongside the event's continued popularity and the considerable media attention it receives each spring.", "The event originated in Sydney in 2007, when the World Wildlife Fund organized a single-city lights-off campaign intended less as a serious emissions-reduction strategy than as a visible, easily replicable symbol capable of drawing public attention to climate change. Within a few years, the campaign had spread to cities on every inhabited continent, with landmark buildings — the Eiffel Tower, the Sydney Opera House, the Empire State Building — routinely darkened in coordinated fashion, generating photographs that circulate widely on social media and, arguably, do more to promote the event's brand than to shift any underlying pattern of energy consumption.", "For years, the assumption underlying Earth Hour's design was that visible, low-effort participation could meaningfully shift broader public engagement with climate policy. [1] Supporters argue that critiques of the event's negligible emissions impact miss the point entirely, insisting Earth Hour was never intended as a serious reduction strategy but rather as an accessible entry point capable of drawing newcomers into environmental engagement they might not otherwise pursue. [2] There is some evidence to support this framing : several national surveys conducted around participating cities have found modest increases in reported environmental concern in the weeks following the event, though whether this shift in attitude translates into lasting behavioral change remains considerably less certain. [3]", "Less widely discussed, however, is the possibility that Earth Hour may, in certain circumstances, produce a net increase in emissions rather than a decrease. Candles, frequently used to create atmosphere during the hour of darkness, release particulate matter and, per unit of light produced, are considerably less efficient than the electric lighting they temporarily replace. More significantly, in regions where backup power sources are activated during sudden drops in grid demand, the resulting fluctuation can force fossil-fuel plants to ramp output up and down inefficiently, a pattern that some energy analysts contend may, in specific grid configurations, offset a meaningful share of whatever emissions the hour itself avoids. [4]", "A separate line of criticism concerns what psychologists term moral licensing: the tendency of a small, symbolic act of virtue to reduce, rather than reinforce, a person's motivation to pursue more demanding but genuinely consequential behavior afterward. If participating in Earth Hour leaves an individual with the impression that they have adequately discharged their environmental obligations for the year, the event may, paradoxically, dampen enthusiasm for the sustained lifestyle adjustments — reduced air travel, dietary change, home insulation — that carry far greater emissions impact than a single dark hour ever could.", "Corporate participation adds a further complication. Many companies now publicize their involvement in Earth Hour as part of broader sustainability communications, even when their year-round emissions profile remains largely unchanged. Critics have characterized this pattern as a form of greenwashing, in which a highly visible but practically inconsequential gesture is used to project an image of environmental responsibility that a firm's actual operations do not substantiate , potentially misleading consumers who might otherwise scrutinize a company's broader practices more closely.", "None of this necessarily means Earth Hour should be abandoned; its defenders reasonably note that few climate initiatives operate entirely free of symbolic elements, and that dismissing visibility as valueless risks underestimating how public attention shapes policy priorities over time. What seems more defensible is a more modest assessment: that Earth Hour, whatever its merits as an awareness campaign, should not be mistaken for, nor allowed to substitute for, the structural and behavioral changes that any serious reduction in emissions ultimately requires."], questions: [{ q: "According to the passage, Earth Hour was originally intended as _______.", options: ["A serious strategy to rapidly reduce city emissions.", "A visible symbol to draw attention to climate change.", "A mandatory policy for major global business sectors.", "A permanent transition toward renewable energy grids."], answer: 1 }, { q: "The word \"negligible\" in paragraph 1 is closest in meaning to _______.", options: ["enormous", "uncertain", "insignificant", "temporary"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Earth Hour consistently produces measurable, significant carbon emissions reductions.", "Earth Hour raises awareness despite minimal emissions impact and potential side effects.", "Earth Hour succeeds mainly because power plants shut down entirely during the hour.", "Earth Hour should be cancelled because corporate greenwashing ruined its purpose."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a downside of Earth Hour?", options: ["a documented rise in nighttime crime rates", "candles releasing particulate matter into the air", "companies using participation for sustainability messaging", "backup power plants ramping output inefficiently"], answer: 0 }, { q: "According to the passage, what is the concern psychologists describe as \"moral licensing\" in relation to Earth Hour?", options: ["that psychologists have proven Earth Hour causes measurable anxiety in participants", "that moral licensing only affects corporations, never individual participants directly", "that a small symbolic act may reduce motivation for more impactful changes", "that participants often forget to turn their lights back on afterward"], answer: 2 }, { q: "The phrase \"this framing\" in paragraph 3 refers to _______.", options: ["The spread of the campaign across every continent.", "The idea that Earth Hour serves as an entry point.", "The modest increases found in recent national surveys.", "The annual media attention Earth Hour regularly receives."], answer: 1 }, { q: "What is the author's overall purpose in writing this passage?", options: ["To argue that all symbolic environmental campaigns should be banned immediately.", "To evaluate Earth Hour's symbolic value alongside its practical limitations.", "To promote corporate sponsorship of Earth Hour as the best climate path.", "To prove scientifically that Earth Hour causes more harm than good."], answer: 1 }, { q: "The word \"substantiate\" in paragraph 6 is closest in meaning to _______.", options: ["advertise", "verify", "exaggerate", "disguise"], answer: 1 }, { q: "It can be inferred from the passage that the author would most likely agree that _______.", options: ["Earth Hour's symbolic value makes any further discussion of its emissions impact unnecessary", "Earth Hour should be replaced immediately by a mandatory national energy-rationing program", "visibility and public attention play no meaningful role in shaping climate policy over time", "symbolic climate gestures can hold some value but should not replace substantive structural change"], answer: 3 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This assumption, however, has come under increasing scrutiny from researchers who study environmental behavior more broadly.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }] },
    { title: "The Uncertain Timeline of Humanoid Robotics", paragraphs: ["Barely a year now passes without a major technology company unveiling a new humanoid robot prototype, each presented with confident claims about how soon such machines might perform general household or warehouse labor at scale. Yet a closer reading of these announcements reveals a curious asymmetry : the demonstrations are frequently striking, while the accompanying claims about near-term deployment timelines tend to rest on considerably thinner evidence than the polish of the footage might suggest. This gap between demonstrated capability and promised capability is not new to robotics, but it has arguably widened as investment in the field has accelerated over the past several years.", "The engineering challenges underlying general-purpose humanoid robots remain, by most technical accounts, substantial. Replicating human-level dexterity — the ability to manipulate irregularly shaped objects, adjust grip force in real time, and recover gracefully from unexpected obstacles — continues to outpace what current actuator and sensor technology can reliably deliver outside carefully controlled settings. Battery life presents a further constraint: many prototypes capable of impressive short demonstrations can sustain only a fraction of a standard working shift before requiring a lengthy recharge, a limitation rarely mentioned in promotional material. Whether these constraints represent temporary engineering hurdles likely to be resolved within a few product cycles, or more fundamental limits requiring entirely new approaches, remains a question on which even specialists within the field are far from unanimous.", "Proponents of rapid adoption typically ground their optimism in economic reasoning rather than purely technical projections. Persistent labor shortages in sectors such as warehousing, elder care, and manufacturing, they argue, create powerful financial incentive for continued investment, and falling component costs — echoing the trajectory once seen in industrial robotic arms — could plausibly compress the timeline between prototype and commercially viable product. This argument is not without merit, but it arguably assumes that cost reduction alone can substitute for capability gains that remain, at present, considerably more difficult to solve than component pricing.", "Skeptics, for their part, frequently invoke the field's own history as a caution against overconfident timelines. Robotics has experienced at least two prior periods — often labeled 'AI winters' by researchers — during which bold predictions about near-term general-purpose automation failed to materialize, followed by extended periods of reduced investment and diminished public interest. Whether the current wave of humanoid robotics represents a genuine technical inflection point, distinct from these earlier cycles because of advances in machine learning unavailable during previous booms, or simply another iteration of a familiar hype pattern, is precisely the question on which reasonable observers continue to disagree.", "A distinction worth drawing more carefully than most coverage manages is that between narrow, task-specific robots and genuinely general-purpose humanoid systems. Robots performing repetitive, tightly defined tasks in structured warehouse environments have already demonstrated reliable commercial value for over a decade, a track record rarely disputed. General-purpose humanoids capable of adapting fluidly to unpredictable human environments — a cluttered kitchen, an unfamiliar hospital room — represent a substantially harder engineering problem, and conflating the two categories, as promotional material often does, risks overstating how close the more ambitious version of this technology actually is.", "Economists studying the potential labor-market impact of humanoid robots remain similarly divided, though not always for the reasons popular discourse assumes. Some argue that even partial success in specific sectors could displace workers faster than retraining programs can accommodate, while others contend that historical patterns of automation have consistently created new categories of employment even as they eliminated old ones, suggesting net effects may prove less disruptive than headline predictions imply. Both camps, notably, tend to hedge their forecasts considerably once pressed on specific timelines, a caution that stands in sharp contrast to the confidence projected in corporate product announcements.", "Taken together, the available evidence supports neither the most enthusiastic corporate timelines nor the most dismissive skepticism. What it supports, more modestly, is a picture in which meaningful progress continues alongside genuine, unresolved technical constraints — a combination that resists the kind of confident, singular narrative that both technology companies and their critics tend to prefer. Evaluating claims about humanoid robotics, in other words, requires distinguishing carefully between what has been demonstrated, what has been promised, and what remains, for now, still genuinely uncertain."], questions: [{ q: "According to the passage, what limitation of current humanoid robot prototypes is rarely mentioned in promotional material?", options: ["their limited battery life relative to a standard work shift", "their inability to be manufactured outside specialized factories", "their inability to lift objects heavier than a few kilograms", "their high cost compared to industrial robotic arms"], answer: 0 }, { q: "The word \"asymmetry\" in paragraph 1 is closest in meaning to _______.", options: ["mismatch", "improvement", "balance", "agreement"], answer: 0 }, { q: "Based on the passage, it can be inferred that the author views the economic argument for rapid adoption in paragraph 3 as _______.", options: ["reasonable but incomplete, since it may understate remaining capability challenges", "identical in strength to the skeptics' historical argument in paragraph 4", "fully sufficient on its own to guarantee near-term commercial success", "completely without merit and contradicted directly by all available evidence"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Claims about humanoid robot capabilities remain genuinely uncertain and debated.", "Humanoid robots have already replaced most human workers in warehouses globally.", "Economists unanimously agree humanoid robots will eliminate millions of jobs soon.", "Humanoid robots will definitely fail commercially due to permanent battery limits."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned in relation to humanoid robotics?", options: ["the distinction between narrow task-specific robots and general-purpose humanoids", "a specific government regulation requiring safety certification for humanoid robots", "declining costs of robotic components over time", "a historical pattern of \"AI winters\" following overconfident predictions"], answer: 1 }, { q: "The phrase \"these constraints\" in paragraph 2 refers to _______.", options: ["falling component costs in the robotics industry", "promotional demonstrations released by technology companies", "labor shortages in warehousing and elder care", "the dexterity and battery-life limitations described earlier"], answer: 3 }, { q: "According to the passage, what commercial track record do narrow, task-specific robots already have?", options: ["they have only recently been tested in a small number of pilot programs", "they remain more expensive to operate than general-purpose humanoid robots", "they have demonstrated reliable commercial value for over a decade", "they have consistently failed to prove reliable in warehouse settings"], answer: 2 }, { q: "What is the author's primary purpose in writing this passage?", options: ["To argue that government regulation of robotics research must increase.", "To encourage evaluating robotics claims by distinguishing fact from promise.", "To convince readers that humanoid robots pose no threat to employment.", "To promote a specific company's humanoid robot over its competitors."], answer: 1 }, { q: "The word \"conflating\" in paragraph 5 is closest in meaning to _______.", options: ["advertising", "confusing together", "improving", "separating"], answer: 1 }, { q: "According to the passage, what do economists divided on the labor-market impact of humanoid robots have in common?", options: ["they all reject the possibility that new job categories could emerge", "they tend to hedge considerably when pressed on specific timelines", "they all agree corporate product announcements are entirely accurate", "they all predict identical timelines for large-scale job displacement"], answer: 1 }] },
  ] },
];
